<script setup lang="ts">
import AdminLayout from "@/Layouts/AdminLayout.vue";
import { Head, Link, router } from "@inertiajs/vue3";
import { ref } from "vue";
defineOptions({ layout: AdminLayout });
const props = defineProps<{ logs: any; counts: Record<string, number>; filters: { search?: string; status?: string } }>();
const search = ref(props.filters.search || "");
const status = ref(props.filters.status || "");
const labels: Record<string, string> = { submitted:"Pending", administrative_review:"Di Review", revision_requested:"Di Review", eligible:"Di Review", curation:"Di Review", shortlisted:"Di Review", selected:"Diterima", not_selected:"Ditolak", disqualified:"Ditolak" };
const tones: Record<string, string> = { submitted:"pending", administrative_review:"review", revision_requested:"review", eligible:"review", curation:"review", shortlisted:"review", selected:"accepted", not_selected:"rejected", disqualified:"rejected" };
function filter(){ router.get('/admin/status-logs',{search:search.value,status:status.value},{preserveState:true,replace:true}); }
function dateTime(value?:string){ return value ? new Intl.DateTimeFormat('id-ID',{dateStyle:'medium',timeStyle:'short',timeZone:'Asia/Jakarta'}).format(new Date(value)) : '-'; }
</script>
<template>
<Head title="Log Status User" />
<div class="status-log-page">
  <header class="heading"><div><p>RIWAYAT OPERASIONAL</p><h1>Log Status User</h1><span>Pantau status terkini setiap pendaftar beserta admin yang melakukan pembaruan.</span></div><div class="live"><i></i> Data status langsung</div></header>
  <section class="stats"><article><small>Pending</small><strong>{{ counts.pending }}</strong></article><article><small>Di Review</small><strong>{{ counts.review }}</strong></article><article class="accepted"><small>Diterima</small><strong>{{ counts.accepted }}</strong></article><article class="rejected"><small>Ditolak</small><strong>{{ counts.rejected }}</strong></article></section>
  <form class="filters" @submit.prevent="filter"><input v-model="search" placeholder="Cari nama, email, nomor pendaftaran, lagu, atau admin"/><select v-model="status"><option value="">Semua status</option><option value="submitted">Pending</option><option value="administrative_review">Di Review</option><option value="selected">Diterima</option><option value="not_selected">Ditolak</option></select><button>Filter</button></form>
  <section class="log-list">
    <article v-for="log in logs.data" :key="log.id" :class="['log-row', tones[log.status] || 'review']">
      <span class="status-dot"></span>
      <div class="identity"><small>{{ log.registration_number }}</small><h2>{{ log.full_name }}</h2><p>{{ log.song_title || 'Tanpa judul' }}<template v-if="log.artist_name"> — {{ log.artist_name }}</template></p></div>
      <div class="current"><small>STATUS SAAT INI</small><strong>{{ labels[log.status] || log.status }}</strong><p>{{ log.reason || 'Belum ada catatan status.' }}</p></div>
      <div class="operator"><small>DIPERBARUI OLEH</small><strong>{{ log.updated_by_name || 'Sistem' }}</strong><span v-if="log.updated_by_username">@{{ log.updated_by_username }}</span><time>{{ dateTime(log.status_updated_at || log.submitted_at) }}</time></div>
      <Link :href="`/admin/submissions/${log.id}`">Lihat Detail →</Link>
    </article>
    <div v-if="!logs.data.length" class="empty"><b>Belum ada log status</b><p>Tidak ditemukan pendaftar yang sesuai dengan pencarian.</p></div>
  </section>
  <nav v-if="logs.links?.length>3" class="pagination"><Link v-for="link in logs.links" :key="link.label" :href="link.url||'#'" :class="{active:link.active,disabled:!link.url}" v-html="link.label"/></nav>
</div>
</template>
